fix_replacement:
always_comb begin
  gnt_next = 2'b00;
  if      (last_gnt == 1'b0 && req[1]) gnt_next = 2'b10;
  else if (last_gnt == 1'b0 && req[0]) gnt_next = 2'b01;
  else if (last_gnt == 1'b1 && req[0]) gnt_next = 2'b01;
  else if (last_gnt == 1'b1 && req[1]) gnt_next = 2'b10;
end
always_ff @(posedge clk or negedge rst_n)
  if (!rst_n) gnt <= 2'b00;
  else        gnt <= gnt_next;
